x=np.linspace(0,20,300);low=np.exp(-.5*((x-3)/1.8)**2);high=.72*np.exp(-.5*((x-1)/.9)**2)+.28*np.exp(-.5*((x-12)/3)**2);ax.plot(x,low/low.max(),label='Low correlation',color=ACCENT);ax.plot(x,high/high.max(),label='High correlation',color=BAD);ax.axvspan(7,20,color=BAD,alpha=.1,label='Senior-relevant tail');ax.set_xlabel('Portfolio loss (%)');ax.set_ylabel('Scaled density');ax.set_title('Correlation changes where losses live',loc='left');ax.legend(fontsize=8);ax.grid(alpha=.25)
